const rows=$input.all().map(i=>i.json||{}).filter(r=>r.id!=null);if(!rows.length)return[];
const MENTION='<@U0BQJV2740J>';
const c=(v,m=500)=>String(v??'').replace(/[\r\n]/g,' ').replace(/\s+/g,' ').trim().slice(0,m);
const ids=rows.map(r=>Number(r.id)).filter(Number.isSafeInteger);
const label=r=>{const no=c(r.task_number,30),tt=c(r.task_title,80);return no?('Task '+no+(tt?'「'+tt+'」':'')):(tt?'「'+tt+'」':'タスク不明（内部ID: '+c(r.task_code||'不明',60)+'）');};
const taskKey=r=>c(r.task_number,30)||c(r.task_code,120);
const isResumed=r=>/自動再開に成功/.test(String(r.payload_message||''));
let autoDenied=0,skippedClosed=0,skippedDup=0;
const entries=new Map();
for(const r of rows){
  const ev=String(r.event_type||''),st=String(r.task_status||'');
  // A: Task192 hookが自動拒否しただけの操作は人の対応不要。通知せず件数だけ数える
  if(ev==='approval_required'&&String(r.prompt_state||'')==='blocked_dangerous'){autoDenied++;continue;}
  // C: 既に完了・中止したタスクの停止/承認通知は古い情報なので送らない
  if(ev!=='completed'&&(st==='completed'||st==='cancelled')){skippedClosed++;continue;}
  // B: 過去6時間に同じタスク・同じ理由・同じrunで配信済みなら送らない
  if(ev!=='completed'&&Number(r.prior_same||0)>0){skippedDup++;continue;}
  const kind=ev==='completed'?'done':(ev==='anomaly'||ev==='stopped')?(isResumed(r)?'resumed':'stop'):'approval';
  const group=kind==='resumed'?'stop':kind;
  const key=group+'|'+taskKey(r);
  const cur=entries.get(key);
  if(!cur){entries.set(key,{kind,rows:[r]});continue;}
  cur.rows.push(r);
  if(kind==='resumed')cur.kind='resumed';
}
const list=[...entries.values()];
if(!list.length)return[{json:{send:false,outbox_ids:ids.join(','),text:'',blocks:[]}}];
const order={stop:0,approval:1,resumed:2,done:3};
list.sort((a,b)=>order[a.kind]-order[b.kind]);
const needsHuman=list.some(e=>e.kind==='stop'||e.kind==='approval');
const sections=[];
for(const e of list.slice(0,12)){
  const r=e.rows[e.rows.length-1],first=e.rows[0];
  const reasons=[...new Set(e.rows.map(x=>c(x.reason,120)).filter(Boolean))].join(' / ');
  const run=e.rows.map(x=>c(x.run_ref,20)).find(Boolean)||'';
  const commit=e.rows.map(x=>String(x.commit_hash||'')).find(h=>/^[0-9a-f]{7,40}$/i.test(h))||'';
  let head,lines=[];
  if(e.kind==='done'){head='✅ 完了';const m=c(String(r.payload_message||'').split('\n').slice(2).join(' '),200);if(m)lines.push(m);if(commit)lines.push('commit: '+commit.slice(0,12));}
  else if(e.kind==='resumed'){head='🔄 停止→自動再開済み';lines.push('停止理由: '+(reasons||'不明'));lines.push('対応不要（同じworktree・差分を保持して再開済み）');}
  else if(e.kind==='stop'){head='⚠️ 停止（要確認）';lines.push('停止理由: '+(reasons||'正常完了前に終了'));if(run)lines.push('run: '+run+(commit?' / commit: '+commit.slice(0,12):''));lines.push('作業データ: 差分・worktreeは保全済み');lines.push('ログ: ~/AIInfinity/logs/task163-launch/');lines.push('次のアクション: '+(c(r.recommended_action,300)||'Claude Codeに「Task '+(c(r.task_number,30)||'?')+' の停止を確認して」と依頼してください'));}
  else{head='🟡 人の応答待ち';lines.push('対象: '+(c(r.approval_action,200)||c(r.payload_message,200)||'操作内容を取得できませんでした'));lines.push('理由: '+(reasons||'人間の確認が必要'));if(r.impact)lines.push('影響: '+c(r.impact,200));lines.push('次のアクション: '+(c(r.recommended_action,300)||'Claude Codeに「Task '+(c(r.task_number,30)||'?')+' の応答待ちを確認して」と依頼してください'));}
  if(e.rows.length>1)lines.push('（'+e.rows.length+'件をまとめました）');
  sections.push({head,label:label(first),lines});
}
const rest=list.length-sections.length;
const counts=[];
if(autoDenied)counts.push('自動拒否 '+autoDenied+'件');
if(skippedClosed)counts.push('完了済みタスクの古い通知 '+skippedClosed+'件');
if(skippedDup)counts.push('配信済みの重複 '+skippedDup+'件');
const footer=(rest>0?'ほか '+rest+'件。':'')+(counts.length?'通知を省略: '+counts.join('・')+'（対応不要・DBに記録済み）':'');
const title=needsHuman?'⚠️ 開発通知（要確認あり）':'開発通知（対応不要）';
const blocks=[{type:'header',text:{type:'plain_text',text:title,emoji:true}}];
for(const s of sections)blocks.push({type:'section',text:{type:'mrkdwn',text:(s.head+'  *'+s.label.replace(/[*_~]/g,'')+'*\n'+s.lines.map(x=>'• '+x).join('\n')).slice(0,2900)}});
if(footer)blocks.push({type:'context',elements:[{type:'mrkdwn',text:footer.slice(0,2900)}]});
const text=((needsHuman?MENTION+' ':'')+[title,...sections.map(s=>s.head+' '+s.label+' '+s.lines.join(' / ')),footer].filter(Boolean).join('\n')).slice(0,2800);
if(needsHuman)blocks.splice(1,0,{type:'section',text:{type:'mrkdwn',text:MENTION}});
return[{json:{send:true,outbox_ids:ids.join(','),text,blocks}}];

